/* CMatrix's inline members (DWARF names Z:\dev\gamez\zmath\zmath_matrix.h as the class's header;
 * MW binding 13: the ELF keeps one copy in a unit that used each). The class itself is declared in
 * zmath.h, which includes this file after it. */
#ifndef ZMATH_MATRIX_H
#define ZMATH_MATRIX_H

#include "gamez/zMath/zmath.h"

/* __opRA4_A4_Cf__7CMatrixCFv (0x223170): jr ra / move v0,a0 - the matrix's own rows
 * (CNode::ComputeFacadeMatrix 0x229734 and CLensFlareSaturate::Tick 0x3bda04 copy a product
 * matrix through it) */
inline CMatrix::operator const CMatrix::rows_t&() const
{
	return m_matrix;
}

/* Transform__7CMatrixCFP6CPnt3Di (0x1eb350): p = row0*x + row1*y + row2*z + row3 (VU0
 * vmula/vmadd, w taken as 1), in place. ELF quirk kept: the count is tested after the first
 * point (count 0 runs on) */
inline void CMatrix::Transform(CPnt3D* points, s32 count) const
{
	do
	{
		f32 px = points->x, py = points->y, pz = points->z;
		points->x = m_matrix[0][0] * px + m_matrix[1][0] * py + m_matrix[2][0] * pz + m_matrix[3][0];
		points->y = m_matrix[0][1] * px + m_matrix[1][1] * py + m_matrix[2][1] * pz + m_matrix[3][1];
		points->z = m_matrix[0][2] * px + m_matrix[1][2] * py + m_matrix[2][2] * pz + m_matrix[3][2];
		points++;
	} while (--count != 0);
}

/* Transform__7CMatrixCFPC6CPnt3DP6CPnt3Di (0x1f5ef0): as above, in -> out (the point is read
 * whole before out is written, so in == out works); the same count quirk */
inline void CMatrix::Transform(const CPnt3D* in, CPnt3D* out, s32 count) const
{
	do
	{
		f32 px = in->x, py = in->y, pz = in->z;
		out->x = m_matrix[0][0] * px + m_matrix[1][0] * py + m_matrix[2][0] * pz + m_matrix[3][0];
		out->y = m_matrix[0][1] * px + m_matrix[1][1] * py + m_matrix[2][1] * pz + m_matrix[3][1];
		out->z = m_matrix[0][2] * px + m_matrix[1][2] * py + m_matrix[2][2] * pz + m_matrix[3][2];
		in++;
		out++;
	} while (--count != 0);
}

/* Multiply__7CMatrixCFPC7CMatrixP7CMatrix (0x218de0): tail call sceVu0MulMatrix(out, other, this) */
inline void CMatrix::Multiply(const CMatrix* other, CMatrix* out) const
{
	sceVu0MulMatrix(out->m_matrix, const_cast<float(*)[4]>(other->m_matrix), const_cast<float(*)[4]>(m_matrix));
}

#endif
